package android.text;import java.util.ArrayList;import java.util.List;import java.lang.reflect.Array;/** Mutable host text value plus identity-preserving span records. */public class Editable implements Spanned,Appendable {private final StringBuilder text;private record Span(Object object,int start,int end,int flags){}private final List<Span> spans=new ArrayList<>();public Editable(){this("");}public Editable(CharSequence value){text=new StringBuilder(value==null?"":value.toString());if(value instanceof Spanned source)for(Object span:source.getSpans(0,source.length(),Object.class))setSpan(span,source.getSpanStart(span),source.getSpanEnd(span),source.getSpanFlags(span));}public final void setSpan(Object object,int start,int end,int flags){removeSpan(object);spans.add(new Span(object,start,end,flags));}public final void removeSpan(Object object){spans.removeIf(span->span.object==object);}public Editable replace(int start,int end,CharSequence value){text.replace(start,end,value.toString());spans.removeIf(span->span.start>text.length()||span.end>text.length());return this;}public Editable delete(int start,int end){return replace(start,end,"");}public Editable clear(){text.setLength(0);spans.clear();return this;}@Override public Editable append(CharSequence value){text.append(value);return this;}@Override public Editable append(CharSequence value,int start,int end){text.append(value,start,end);return this;}@Override public Editable append(char value){text.append(value);return this;}@Override public int length(){return text.length();}@Override public char charAt(int index){return text.charAt(index);}@Override public CharSequence subSequence(int start,int end){return text.substring(start,end);}@Override public String toString(){return text.toString();}@Override public <T>T[] getSpans(int start,int end,Class<T> type){List<T> found=new ArrayList<>();for(Span span:spans)if(type.isInstance(span.object)&&span.end>=start&&span.start<=end)found.add(type.cast(span.object));@SuppressWarnings("unchecked")T[] result=(T[])Array.newInstance(type,found.size());return found.toArray(result);}@Override public int getSpanStart(Object object){for(Span span:spans)if(span.object==object)return span.start;return -1;}@Override public int getSpanEnd(Object object){for(Span span:spans)if(span.object==object)return span.end;return -1;}@Override public int getSpanFlags(Object object){for(Span span:spans)if(span.object==object)return span.flags;return 0;}}
